CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN ('admin','editor','viewer')),password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(id text PRIMARY KEY,payload jsonb NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS resources(kind text NOT NULL,id text NOT NULL,draft jsonb NOT NULL,published jsonb,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(kind,id));
CREATE TABLE IF NOT EXISTS layouts(page_key text NOT NULL,profile_id text NOT NULL REFERENCES profiles(id),draft jsonb NOT NULL,published jsonb,revision integer NOT NULL DEFAULT 1,published_version integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(page_key,profile_id));
CREATE TABLE IF NOT EXISTS layout_versions(page_key text NOT NULL,profile_id text NOT NULL REFERENCES profiles(id),version integer NOT NULL,layout jsonb NOT NULL,published_at timestamptz NOT NULL DEFAULT now(),published_by text NOT NULL,PRIMARY KEY(page_key,profile_id,version));
CREATE TABLE IF NOT EXISTS releases(id text PRIMARY KEY,profile_id text NOT NULL REFERENCES profiles(id),version integer NOT NULL,bundle jsonb NOT NULL,bundle_text text NOT NULL,digest text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(profile_id,version));
CREATE TABLE IF NOT EXISTS screens(id text PRIMARY KEY,payload jsonb NOT NULL,profile_id text NOT NULL REFERENCES profiles(id),token_hash text UNIQUE NOT NULL,enabled boolean NOT NULL DEFAULT true,last_seen timestamptz,desired_release text REFERENCES releases(id),applied_release text REFERENCES releases(id),telemetry jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrollments(id text PRIMARY KEY,code text UNIQUE NOT NULL,secret_hash text NOT NULL,metadata jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',expires_at timestamptz NOT NULL,screen_id text REFERENCES screens(id));
CREATE TABLE IF NOT EXISTS deliveries(id text PRIMARY KEY,screen_id text NOT NULL REFERENCES screens(id),release_id text NOT NULL REFERENCES releases(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','received','downloaded','applied','failed','superseded')),attempts integer NOT NULL DEFAULT 0,next_attempt timestamptz NOT NULL DEFAULT now(),last_error text,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(screen_id,release_id));
CREATE INDEX IF NOT EXISTS deliveries_due ON deliveries(next_attempt) WHERE status IN ('pending','received','downloaded','failed');
CREATE TABLE IF NOT EXISTS acknowledgements(id text PRIMARY KEY,delivery_id text NOT NULL REFERENCES deliveries(id),stage text NOT NULL,digest text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),UNIQUE(delivery_id,stage));
CREATE TABLE IF NOT EXISTS schedules(id text PRIMARY KEY,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assets(id text PRIMARY KEY,mime text NOT NULL,bytes bigint NOT NULL,digest text NOT NULL,name text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media_tickets(token_hash text PRIMARY KEY,asset_id text NOT NULL REFERENCES assets(id),screen_id text NOT NULL REFERENCES screens(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS integrations(id text PRIMARY KEY,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY,occurred_at timestamptz NOT NULL DEFAULT now(),actor text NOT NULL,action text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,detail jsonb NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS audit_time ON audit(occurred_at DESC);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
